    const workerCode = `
      self.onmessage = async (e) => {
        const reader = e.data.getReader();
        await reader.read(); // consume one chunk; the stream stays open
        await reader.cancel("stop"); // cancel while still open
        self.postMessage("done");
        self.close();
      };
    `;
