func (l *browseTemplateContext) applySortAndLimit(sortParam, orderParam, limitParam string, offsetParam string) {
	l.Sort = sortParam
	l.Order = orderParam

	// precompute each item's lowercase name once, up front (O(n)), instead
	// of letting byName/byNameDirFirst/bySize recompute it on every one of
	// the O(n log n) comparisons sort.Sort makes
	for i := range l.Items {
		l.Items[i].nameLower = strings.ToLower(l.Items[i].Name)
	}

	if l.Order == "desc" {
		switch l.Sort {
		case sortByName:
			sort.Sort(sort.Reverse(byName(*l)))
		case sortByNameDirFirst:
			sort.Sort(sort.Reverse(byNameDirFirst(*l)))
		case sortBySize:
			sort.Sort(sort.Reverse(bySize(*l)))
		case sortByTime:
			sort.Sort(sort.Reverse(byTime(*l)))
		}
	} else {
		switch l.Sort {
		case sortByName:
			sort.Sort(byName(*l))
