            long bytesTwo = queuedBytesAtDepth(opi, 2);
            long bytesThree = queuedBytesAtDepth(opi, 3);
            assertTrue("third group must contribute bytes so a 2-group budget is distinguishable", bytesThree > bytesTwo);

