		{name: "rtmin plus", signal: runtime.Signal_SIGNAL_SIGRTMINPLUS1, expectedSignal: "SIGRTMIN+1"},
		{name: "rtmax minus", signal: runtime.Signal_SIGNAL_SIGRTMAXMINUS1, expectedSignal: "SIGRTMAX-1"},
